-- mock_data_import.sql
-- 虚拟AI产品数据集建表及数据导入语句
-- 数据由 generate_mock_data.py 生成
-- 包含4张表：users / ai_events / orders / llm_calls
-- 使用方法：复制全部内容粘贴进SQLiteOnline代码框，点击Run执行
-- 执行后验证：
-- SELECT COUNT(*) FROM users;      应返回1000
-- SELECT COUNT(*) FROM ai_events;  应返回2470
-- SELECT COUNT(*) FROM orders;     应返回159
-- SELECT COUNT(*) FROM llm_calls;  应返回495
# 适合不会Python、想直接开始练SQL的人,复制粘贴即可运行

01_create_users.sql
